import {createPskov,pskovCells,pskovCrown,pskovNotation,readPskov,generatePskovMoves,applyPskovMove,pskovPositionKey,pskovResult,pskovView,type PskovState,type PskovPiece} from './pskovRules';
const man=(q:number,r:number,player:0|1=0,type:PskovPiece['type']='man'):PskovPiece=>({q,r,player,type});
const position=(pieces:PskovPiece[],activePlayer:0|1=0):PskovState=>{const s:PskovState={variant:'pskov',pieces,activePlayer,ply:0,history:[],quietPly:0,borderDue:[]};s.history=[pskovPositionKey(s)];return s;};
describe('Pskov standard 37-cell rules',()=>{
 it('matches the documented 13-a-side setup and opposite corner notation',()=>{const s=createPskov();expect(pskovCells().length).toBe(37);expect(new Set(pskovCells().map(pskovNotation)).size).toBe(37);expect(s.pieces.filter(p=>p.player===0).length).toBe(13);expect(s.pieces.filter(p=>p.player===1).length).toBe(13);expect(s.pieces.every(p=>p.player===0?2*p.r+p.q<=-2:2*p.r+p.q>=2)).toBeTrue();expect(pskovNotation({q:0,r:3})).toBe('d7');expect(pskovNotation({q:0,r:-3})).toBe('d1');expect(pskovCells().filter(h=>pskovCrown(0,h))).toEqual([{q:0,r:3}]);expect(readPskov(s)).toEqual(s);expect(generatePskovMoves(s).length).toBe(13);});
 it('gives a man three forward steps and six backward or forward captures',()=>{const s=position([man(0,0),man(3,0,1)]);expect(generatePskovMoves(s).map(m=>m.to)).toEqual([{q:1,r:0},{q:0,r:1},{q:-1,r:1}]);for(const[q,r]of [[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]]){const moves=generatePskovMoves(position([man(0,0),man(q,r,1)]));expect(moves.length).toBe(1);expect(moves[0].to).toEqual({q:q*2,r:r*2});}});
 it('requires complete captures but preserves a shorter complete choice',()=>{const s=position([man(0,-2),man(-2,2),man(0,-1,1),man(1,0,1),man(-1,2,1)]),moves=generatePskovMoves(s);expect(moves.some(m=>m.captures.length===2)).toBeTrue();expect(moves.some(m=>m.captures.length===1)).toBeTrue();const long=moves.find(m=>m.captures.length===2)!;expect(()=>applyPskovMove(s,{from:long.from,to:long.path[1],path:long.path.slice(0,2)})).toThrowError(/Illegal move/);expect(applyPskovMove(s,long).state.ply).toBe(1);});
 it('ends a man capture on the opposite corner and crowns for the following turn',()=>{const s=position([man(0,1),man(0,2,1),man(-1,3,1)]),moves=generatePskovMoves(s);expect(moves.length).toBe(1);expect(moves[0].path).toEqual([{q:0,r:1},{q:0,r:3}]);expect(moves[0].captures.length).toBe(1);const next=applyPskovMove(s,moves[0]).state;expect(next.pieces.find(p=>p.player===0)?.type).toBe('draughts-king');expect(next.pieces.filter(p=>p.player===1).length).toBe(1);expect(next.activePlayer).toBe(1);const edge=position([man(-1,2),man(3,-2,1)]),m=generatePskovMoves(edge).find(m=>m.to.q===-1&&m.to.r===3)!;expect(applyPskovMove(edge,m).state.pieces.find(p=>p.player===0)?.type).toBe('man');});
 it('uses flying kings and leaves captured blockers until the full turn ends',()=>{const s=position([man(0,0,0,'draughts-king'),man(0,1,1),man(0,-1,1)]),moves=generatePskovMoves(s);expect(moves.length).toBe(4);expect(moves.every(m=>m.captures.length===1)).toBeTrue();expect(moves.map(m=>m.to.r).sort()).toEqual([-2,-3,2,3].sort());const friendly=position([man(0,0,0,'draughts-king'),man(0,1),man(0,2,1)]);expect(generatePskovMoves(friendly).some(m=>m.from.q===0&&m.from.r===0&&m.to.q===0&&m.to.r>0)).toBeFalse();});
 it('permits return-to-origin capture routes without capturing an enemy twice',()=>{const s=position([man(0,0),man(1,0,1),man(1,1,1),man(0,1,1)]),move=generatePskovMoves(s).find(m=>m.to.q===0&&m.to.r===0)!;expect(move.captures.length).toBe(3);const next=applyPskovMove(s,move).state;expect(next.pieces.length).toBe(1);expect(pskovResult(next).winner).toBe(0);expect(pskovView(s).legalMoves.find(m=>JSON.stringify(m.path)===JSON.stringify(move.path))?.changes?.find(c=>c.q===0&&c.r===0)?.piece?.player).toBe(0);});
 it('adjudicates captured, blocked, agreed and repetition results without chess material draws',()=>{expect(pskovResult(position([man(0,0,1)])).winner).toBe(1);expect(pskovResult(position([man(3,0),man(0,3),man(-3,3),man(0,-3,1)])).status).toBe('ongoing');const s=position([man(3,0),man(2,1,1),man(1,2,1)]);expect(pskovResult(s).reason).toBe('blocked');const kings=position([man(0,0,0,'draughts-king'),man(3,0,1,'draughts-king')]);expect(pskovResult(kings).status).toBe('ongoing');kings.history=Array(3).fill(pskovPositionKey(kings));expect(pskovResult(kings).reason).toBe('repetition');kings.agreed=true;expect(pskovResult(kings).reason).toBe('agreed');kings.resigned=0;expect(pskovResult(kings).winner).toBe(1);});
